import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Banknote, CalendarDays, Check, CircleDollarSign, Pencil, Plus, Receipt, RotateCcw, Search, WalletCards, X } from 'lucide-react';
import type { PsychologyPatient, PsychologySessionPackageInput, PsychologyStore } from './psychologyDomain';
import {
  cancelPsychologyCharge,
  createPsychologyChargeInLedger,
  createPsychologyExpenseInLedger,
  createPsychologyPaymentInLedger,
  createPsychologyPeriod,
  createPsychologySessionPackageInLedger,
  getPsychologyFinancialLedger,
  getPsychologyFinancialOverview,
  isPsychologyPaymentActive,
  psychologyCivilDate,
  reactivatePsychologyCharge,
  reactivatePsychologyExpense,
  reactivatePsychologyPayment,
  reversePsychologyExpense,
  reversePsychologyPayment,
  updatePsychologyChargeInLedger,
  updatePsychologyExpenseInLedger,
  updatePsychologyPaymentInLedger,
  upsertPsychologySessionPackageInLedger,
  type PsychologyCanonicalChargeStatus,
  type PsychologyExpenseInput,
  type PsychologyFinancialPeriod,
  type PsychologyLedgerMutation,
  type PsychologyPeriodPreset,
} from './psychologyFinancialLedger';
import type { PsychologyCharge, PsychologyExpense, PsychologyExpenseCategory, PsychologyExpenseStatus, PsychologyPayment, PsychologyPaymentMethod, PsychologySessionPackage } from './psychologyR2a';
import { formatPsychologyMoney, formatPsychologyMoneyInput, parsePsychologyMoney } from './psychologyMoney';

const inputClass = 'w-full rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-3 text-sm text-slate-900 outline-none transition focus:border-violet-600 focus:ring-2 focus:ring-violet-100';
const primaryButton = 'inline-flex items-center justify-center gap-2 rounded-xl bg-violet-700 px-4 py-3 text-sm font-black text-white shadow-sm transition hover:bg-violet-800 disabled:cursor-not-allowed disabled:opacity-50';
const secondaryButton = 'inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-black text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50';
const smallButton = 'inline-flex items-center justify-center gap-1.5 rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-xs font-black text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50';
const categories: PsychologyExpenseCategory[] = ['Aluguel', 'Materiais', 'Serviços', 'Impostos/Taxas', 'Marketing', 'Capacitação', 'Tecnologia', 'Outros'];
const paymentMethods: Array<{ value: PsychologyPaymentMethod; label: string }> = [{ value: 'PIX', label: 'Pix' }, { value: 'CASH', label: 'Dinheiro' }, { value: 'CARD', label: 'Cartão' }, { value: 'TRANSFER', label: 'Transferência' }, { value: 'OTHER', label: 'Outro' }];

type FinanceTab = 'overview' | 'charges' | 'payments' | 'expenses' | 'packages';
type Modal = 'charge' | 'payment' | 'expense' | 'package' | { type: 'charge' | 'payment' | 'expense' | 'package' | 'paymentForCharge'; id: string } | null;
type ReasonRequest = { type: 'charge' | 'payment' | 'expense'; id: string };
type ChargeDraft = { patientId: string; description: string; money: string; dueDate: string; sessionId: string; serviceId: string; packageId: string; exempt: boolean; exemptionReason: string };

function dateLabel(value?: string): string {
  if (!value) return 'Sem vencimento';
  return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(`${value.slice(0, 10)}T12:00:00`));
}

function chargeStatusLabel(status: PsychologyCanonicalChargeStatus, overdue = false): string {
  if (status === 'CANCELLED') return 'Cancelada';
  if (status === 'EXEMPT') return 'Isento / cortesia';
  if (overdue) return 'Vencida';
  if (status === 'PAID') return 'Paga';
  if (status === 'PARTIALLY_PAID') return 'Parcialmente paga';
  return 'Pendente';
}

function statusClass(status: PsychologyCanonicalChargeStatus, overdue = false): string {
  if (status === 'CANCELLED') return 'bg-slate-100 text-slate-600';
  if (status === 'EXEMPT') return 'bg-violet-50 text-violet-700';
  if (overdue) return 'bg-rose-50 text-rose-700';
  if (status === 'PAID') return 'bg-emerald-50 text-emerald-700';
  if (status === 'PARTIALLY_PAID') return 'bg-amber-50 text-amber-700';
  return 'bg-slate-100 text-slate-700';
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return <label className="block space-y-1.5"><span className="text-xs font-black text-slate-600">{label}</span>{children}</label>;
}

function FinanceDialog({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  return <div className="fixed inset-0 z-[230] flex items-center justify-center bg-slate-950/45 p-4" role="dialog" aria-modal="true"><section className={`max-h-[92vh] w-full ${wide ? 'max-w-3xl' : 'max-w-xl'} overflow-y-auto rounded-3xl bg-white shadow-2xl`}><header className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><p className="text-[10px] font-black uppercase tracking-[0.16em] text-violet-700">Financeiro · Psicologia</p><h2 className="mt-1 text-lg font-black text-slate-900">{title}</h2></div><button type="button" onClick={onClose} aria-label="Fechar" className="rounded-xl p-2 text-slate-500 hover:bg-slate-100"><X size={18} /></button></header><div className="space-y-4 p-5">{children}</div></section></div>;
}

function MoneyInput({ value, onChange, placeholder = 'R$ 0,00', autoFocus = false }: { value: string; onChange: (value: string) => void; placeholder?: string; autoFocus?: boolean }) {
  const formatWhileTyping = (nextValue: string) => {
    const formatted = formatPsychologyMoneyInput(nextValue);
    onChange(formatted || nextValue);
  };
  return <input autoFocus={autoFocus} value={value} onChange={event => formatWhileTyping(event.target.value)} onBlur={() => formatWhileTyping(value)} inputMode="decimal" placeholder={placeholder} className={inputClass} aria-describedby="psychology-money-help" />;
}

function OverviewCard({ label, value, tone }: { label: string; value: string; tone: 'violet' | 'emerald' | 'amber' | 'rose' | 'slate' }) {
  const tones = { violet: 'border-violet-200 bg-violet-50/70', emerald: 'border-emerald-200 bg-emerald-50/70', amber: 'border-amber-200 bg-amber-50/70', rose: 'border-rose-200 bg-rose-50/70', slate: 'border-slate-200 bg-white' };
  return <article className={`rounded-2xl border p-4 shadow-sm ${tones[tone]}`}><p className="text-[11px] font-black uppercase tracking-[0.12em] text-slate-500">{label}</p><p className="mt-2 text-2xl font-black text-slate-950">{value}</p></article>;
}

export default function PsychologyFinanceView({ store, patientId, patientName, onStoreChange, onNotice, onRemoteMutation, remoteWriteBlocked = false }: { store: PsychologyStore; patientId?: string; patientName?: string; onStoreChange: (store: PsychologyStore) => boolean | Promise<boolean>; onNotice: (message: string) => void; onRemoteMutation?: (mutation: PsychologyLedgerMutation) => boolean | Promise<boolean>; remoteWriteBlocked?: boolean }) {
  const [tab, setTab] = useState<FinanceTab>('overview');
  const [modal, setModal] = useState<Modal>(null);
  const [reasonRequest, setReasonRequest] = useState<ReasonRequest | null>(null);
  const [reason, setReason] = useState('');
  const [preset, setPreset] = useState<PsychologyPeriodPreset>('month');
  const [customStart, setCustomStart] = useState(psychologyCivilDate());
  const [customEnd, setCustomEnd] = useState(psychologyCivilDate());
  const [search, setSearch] = useState('');
  const [chargeFilter, setChargeFilter] = useState('all');
  const [paymentFilter, setPaymentFilter] = useState('all');
  const [expenseFilter, setExpenseFilter] = useState('all');
  const [packageFilter, setPackageFilter] = useState('all');
  const [processing, setProcessing] = useState(false);
  const [chargeDraft, setChargeDraft] = useState<ChargeDraft | null>(null);
  const mutationLock = useRef(false);
  const period = useMemo<PsychologyFinancialPeriod>(() => createPsychologyPeriod(preset, new Date(), customStart, customEnd), [customEnd, customStart, preset]);
  const financeStore = useMemo(() => patientId ? {
    ...store,
    charges: store.charges.filter(charge => charge.patientId === patientId),
    payments: store.payments.filter(payment => payment.patientId === patientId),
    expenses: [],
  } : store, [patientId, store]);
  const ledger = useMemo(() => getPsychologyFinancialLedger(financeStore), [financeStore]);
  const overview = useMemo(() => getPsychologyFinancialOverview(financeStore, period), [financeStore, period]);
  const patientMap = useMemo(() => new Map<string, PsychologyPatient>(store.patients.map(patient => [patient.id, patient])), [store.patients]);
  const serviceMap = useMemo(() => new Map(store.services.map(service => [service.id, service])), [store.services]);
  const packageMap = useMemo(() => new Map(store.sessionPackages.map(item => [item.id, item])), [store.sessionPackages]);
  const activePackages = useMemo(() => store.sessionPackages.filter(item => (!patientId || item.patientId === patientId) && item.active && item.usedSessions < item.totalSessions), [patientId, store.sessionPackages]);
  const charges = useMemo(() => ledger.chargeEntries.filter(entry => {
    if (patientId && entry.charge.patientId !== patientId) return false;
    const patient = entry.charge.patientId ? patientMap.get(entry.charge.patientId)?.name || '' : 'Paciente excluído';
    const matchesSearch = !search.trim() || `${patient} ${entry.charge.description || ''} ${serviceMap.get(entry.charge.serviceId || '')?.name || ''} ${packageMap.get(entry.charge.packageId || '')?.name || ''}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase());
    const matchesFilter = chargeFilter === 'all' || (chargeFilter === 'overdue' ? entry.overdue : chargeFilter === entry.status.toLowerCase());
    return matchesSearch && matchesFilter;
  }), [chargeFilter, ledger.chargeEntries, packageMap, patientId, patientMap, search, serviceMap]);
  const payments = useMemo(() => ledger.payments.filter(payment => {
    if (patientId && payment.patientId !== patientId) return false;
    const patient = payment.patientId ? patientMap.get(payment.patientId)?.name || '' : 'Paciente excluído';
    const charge = ledger.charges.find(item => item.id === payment.chargeId);
    const matchesSearch = !search.trim() || `${patient} ${charge?.description || ''} ${charge?.packageId ? packageMap.get(charge.packageId)?.name || '' : ''} ${payment.method}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase());
    const matchesFilter = paymentFilter === 'all' || (paymentFilter === 'active' ? isPsychologyPaymentActive(payment) : !isPsychologyPaymentActive(payment));
    return matchesSearch && matchesFilter;
  }), [ledger.charges, ledger.payments, packageMap, patientId, patientMap, paymentFilter, search]);
  const expenses = useMemo(() => ledger.expenses.filter(expense => {
    const matchesSearch = !search.trim() || `${expense.description || ''} ${expense.category} ${expense.status}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase());
    const matchesFilter = expenseFilter === 'all' || expense.status === expenseFilter;
    return matchesSearch && matchesFilter;
  }), [expenseFilter, ledger.expenses, search]);
  const packages = useMemo(() => store.sessionPackages.filter(item => {
    if (patientId && item.patientId !== patientId) return false;
    const patient = patientMap.get(item.patientId)?.name || '';
    const matchesSearch = !search.trim() || `${patient} ${item.name} ${serviceMap.get(item.serviceId || '')?.name || ''}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase());
    const matchesFilter = packageFilter === 'all' || (packageFilter === 'active' ? item.active : !item.active);
    return matchesSearch && matchesFilter;
  }), [packageFilter, patientId, patientMap, search, serviceMap, store.sessionPackages]);
  const availableTabs: Array<[FinanceTab, string]> = patientId
    ? [['overview', 'Visão geral'], ['charges', 'Cobranças'], ['packages', 'Pacotes'], ['payments', 'Pagamentos']]
    : [['overview', 'Visão geral'], ['charges', 'Cobranças'], ['packages', 'Pacotes'], ['payments', 'Pagamentos'], ['expenses', 'Despesas']];
  useEffect(() => {
    if (patientId && tab === 'expenses') setTab('overview');
  }, [patientId, tab]);

  const saveMutation = (result: PsychologyLedgerMutation, success: string, onSuccess?: () => void): boolean | Promise<boolean> => {
    if (result.error) { onNotice(result.error); return false; }
    if (remoteWriteBlocked) { onNotice('Aguarde o carregamento do provider remoto antes de salvar o financeiro.'); return false; }
    if (processing || mutationLock.current) return false;
    const finish = (saved: boolean): boolean => {
      setProcessing(false);
      mutationLock.current = false;
      if (!saved) { onNotice('Nenhuma alteração financeira foi confirmada.'); return false; }
      onNotice(success);
      setModal(null);
      onSuccess?.();
      return true;
    };
    mutationLock.current = true;
    setProcessing(true);
    if (onRemoteMutation) {
      try {
        const saved = onRemoteMutation(result);
        return saved instanceof Promise ? saved.then(finish).catch(() => finish(false)) : finish(saved);
      } catch { return finish(false); }
    }
    try {
      const saved = onStoreChange(result.store);
      return saved instanceof Promise ? saved.then(finish).catch(() => finish(false)) : finish(saved);
    } catch {
      return finish(false);
    }
  };

  const confirmReason = () => {
    if (!reason.trim() || !reasonRequest) return;
    const result = reasonRequest.type === 'charge' ? cancelPsychologyCharge(store, reasonRequest.id, reason) : reasonRequest.type === 'payment' ? reversePsychologyPayment(store, reasonRequest.id, reason) : reversePsychologyExpense(store, reasonRequest.id, reason);
    const success = reasonRequest.type === 'charge' ? 'Cobrança cancelada.' : reasonRequest.type === 'payment' ? 'Pagamento estornado.' : 'Despesa estornada.';
    void Promise.resolve(saveMutation(result, success, () => { setReasonRequest(null); setReason(''); }));
  };

  const saveEdit = (result: PsychologyLedgerMutation, success: string) => { void Promise.resolve(saveMutation(result, success)); };
  const disabled = remoteWriteBlocked || processing;
  const tabLabel = tab === 'charges' ? 'Buscar paciente ou descrição' : tab === 'payments' ? 'Buscar paciente, cobrança ou meio' : tab === 'expenses' ? 'Buscar descrição ou categoria' : 'Buscar paciente, pacote ou serviço';
  return <div className="space-y-5" data-testid="psychology-finance" data-patient-id={patientId || undefined} aria-busy={processing}>
    <div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-black uppercase tracking-[0.16em] text-violet-700">Financeiro administrativo</p><h3 className="mt-1 text-2xl font-black tracking-tight text-slate-950">{patientName ? `Financeiro de ${patientName}` : 'Financeiro profissional da Psicologia'}</h3><p className="mt-2 text-sm text-slate-500">{patientName ? 'Cobranças, pacotes e pagamentos vinculados a este paciente.' : 'Cobranças, pacotes, pagamentos e despesas no escopo autenticado da Psicologia.'}</p></div><div className="flex flex-wrap gap-2"><button type="button" onClick={() => setModal('charge')} disabled={remoteWriteBlocked || processing} className={primaryButton}><Plus size={16} /> Nova cobrança</button><button type="button" onClick={() => setModal('package')} disabled={remoteWriteBlocked || processing} className={secondaryButton}><WalletCards size={16} /> Novo pacote</button><button type="button" onClick={() => setModal('payment')} disabled={remoteWriteBlocked || processing} className={secondaryButton}><WalletCards size={16} /> Registrar pagamento</button>{!patientId && <button type="button" onClick={() => setModal('expense')} disabled={remoteWriteBlocked || processing} className={secondaryButton}><Banknote size={16} /> Nova despesa</button>}</div></div>
    <p id="psychology-money-help" className="text-xs font-semibold text-slate-500">Valores aceitam vírgula, ponto, colagem e formato brasileiro; ao sair do campo são apresentados em BRL.</p>
    {remoteWriteBlocked && <div role="status" data-testid="psychology-finance-remote-readonly" className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-900">Provider remoto ativo: carregando a consulta financeira; Escrita financeira remota ainda não disponível até o carregamento.</div>}
    <section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2" role="group" aria-label="Período financeiro">{([['week', 'Esta semana'], ['month', 'Este mês'], ['year', 'Este ano'], ['custom', 'Personalizado']] as const).map(([value, label]) => <button type="button" key={value} onClick={() => setPreset(value)} className={`rounded-xl px-3 py-2 text-xs font-black ${preset === value ? 'bg-violet-700 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}>{label}</button>)}</div><span className="text-xs font-bold text-slate-500">{dateLabel(period.startDate)} até {dateLabel(period.endDate)}</span></div>{preset === 'custom' && <div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="Data inicial"><input type="date" value={customStart} onChange={event => setCustomStart(event.target.value)} className={inputClass} /></Field><Field label="Data final"><input type="date" value={customEnd} onChange={event => setCustomEnd(event.target.value)} className={inputClass} /></Field></div>}</section>
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5"><OverviewCard label="Recebido no período" value={formatPsychologyMoney(overview.received)} tone="emerald" /><OverviewCard label="A receber" value={formatPsychologyMoney(overview.receivable)} tone="amber" /><OverviewCard label="Vencido" value={formatPsychologyMoney(overview.overdue)} tone="rose" /><OverviewCard label="Despesas no período" value={formatPsychologyMoney(overview.expenses)} tone="slate" /><OverviewCard label="Saldo realizado" value={formatPsychologyMoney(overview.balance)} tone={overview.balance >= 0 ? 'violet' : 'rose'} /></div>
    <div className="flex gap-2 overflow-x-auto border-b border-slate-200" role="tablist" aria-label="Áreas financeiras">{availableTabs.map(([value, label]) => <button type="button" role="tab" aria-selected={tab === value} key={value} onClick={() => setTab(value)} className={`whitespace-nowrap border-b-2 px-3 py-3 text-sm font-black ${tab === value ? 'border-violet-700 text-violet-700' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>{label}</button>)}</div>
    {tab === 'overview' && <OverviewPanel overview={overview} onTab={setTab} packageCount={activePackages.length} />}
    {tab !== 'overview' && <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row"><label className="relative min-w-0 flex-1"><Search size={16} className="absolute left-3 top-3.5 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} placeholder={tabLabel} className={`${inputClass} pl-9`} /></label>{tab === 'charges' && <select value={chargeFilter} onChange={event => setChargeFilter(event.target.value)} className={`${inputClass} sm:w-52`}><option value="all">Todas as cobranças</option><option value="pending">Pendentes</option><option value="partially_paid">Parcialmente pagas</option><option value="paid">Pagas</option><option value="overdue">Vencidas</option><option value="exempt">Isentas</option><option value="cancelled">Canceladas</option></select>}{tab === 'packages' && <select value={packageFilter} onChange={event => setPackageFilter(event.target.value)} className={`${inputClass} sm:w-44`}><option value="all">Todos os pacotes</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select>}{tab === 'payments' && <select value={paymentFilter} onChange={event => setPaymentFilter(event.target.value)} className={`${inputClass} sm:w-44`}><option value="all">Todos os pagamentos</option><option value="active">Ativos</option><option value="reversed">Estornados</option></select>}{tab === 'expenses' && <select value={expenseFilter} onChange={event => setExpenseFilter(event.target.value)} className={`${inputClass} sm:w-44`}><option value="all">Todas as despesas</option><option value="REALIZED">Realizadas</option><option value="PENDING">Pendentes</option><option value="REVERSED">Estornadas</option></select>}</div>{tab === 'charges' && <ChargesList charges={charges} patientMap={patientMap} serviceMap={serviceMap} packageMap={packageMap} onCancel={id => { setReasonRequest({ type: 'charge', id }); setReason(''); }} onReactivate={id => saveEdit(reactivatePsychologyCharge(store, id), 'Cobrança reativada.')} onEdit={id => setModal({ type: 'charge', id })} onPay={id => setModal({ type: 'paymentForCharge', id })} writeBlocked={disabled} />}{tab === 'packages' && <PackagesList packages={packages} patientMap={patientMap} serviceMap={serviceMap} chargeEntries={ledger.chargeEntries} onEdit={id => setModal({ type: 'package', id })} onPay={id => { const entry = ledger.chargeEntries.find(candidate => candidate.charge.packageId === id && candidate.balance > 0); if (entry) setModal({ type: 'paymentForCharge', id: entry.charge.id }); else onNotice('Crie uma cobrança para este pacote antes de registrar o pagamento.'); }} onToggle={item => saveEdit(upsertPsychologySessionPackageInLedger(store, { patientId: item.patientId, name: item.name, totalSessions: item.totalSessions, usedSessions: item.usedSessions, startDate: item.startDate, endDate: item.endDate, active: !item.active, price: item.price, serviceId: item.serviceId, pricePerSession: item.pricePerSession, totalPrice: item.totalPrice }, item.id), item.active ? 'Pacote desativado.' : 'Pacote reativado.')} writeBlocked={disabled} />}{tab === 'payments' && <PaymentsList payments={payments} charges={ledger.charges} patientMap={patientMap} packageMap={packageMap} onReverse={id => { setReasonRequest({ type: 'payment', id }); setReason(''); }} onReactivate={id => saveEdit(reactivatePsychologyPayment(store, id), 'Pagamento reativado.')} onEdit={id => setModal({ type: 'payment', id })} writeBlocked={disabled} />}{tab === 'expenses' && !patientId && <ExpensesList expenses={expenses} onReverse={id => { setReasonRequest({ type: 'expense', id }); setReason(''); }} onReactivate={id => saveEdit(reactivatePsychologyExpense(store, id), 'Despesa reativada.')} onEdit={id => setModal({ type: 'expense', id })} writeBlocked={disabled} />}</section>}
    {modal === 'charge' && <ChargeDialog store={store} initialPatientId={patientId} initialDraft={chargeDraft || undefined} onClose={() => { setChargeDraft(null); setModal(null); }} onCreatePackage={draft => { setChargeDraft(draft); setModal('package'); }} onSave={input => void Promise.resolve(saveMutation(createPsychologyChargeInLedger(store, input), 'Cobrança criada.', () => setChargeDraft(null)))} />}
    {modal === 'payment' && <PaymentDialog store={store} patientId={patientId} onClose={() => setModal(null)} onSave={input => void Promise.resolve(saveMutation(createPsychologyPaymentInLedger(store, input), 'Pagamento registrado.'))} />}
    {modal === 'expense' && <ExpenseDialog onClose={() => setModal(null)} onSave={input => void Promise.resolve(saveMutation(createPsychologyExpenseInLedger(store, input), 'Despesa criada.'))} />}
    {modal === 'package' && <PackageDialog store={store} initialPatientId={chargeDraft?.patientId || patientId} onClose={() => { setChargeDraft(null); setModal(null); }} onSave={input => { const result = createPsychologySessionPackageInLedger(store, input); const createdPackage = result.store.sessionPackages.find(item => !store.sessionPackages.some(existing => existing.id === item.id)); void Promise.resolve(saveMutation(result, 'Pacote criado.', () => { if (chargeDraft && createdPackage) { setChargeDraft(current => current ? { ...current, packageId: createdPackage.id, serviceId: input.serviceId || current.serviceId, money: formatPsychologyMoneyInput(input.totalPrice ?? input.price ?? 0) } : current); setModal('charge'); } else setChargeDraft(null); })); }} />}
    {modal !== null && typeof modal === 'object' && modal.type === 'charge' && <ChargeEditDialog store={store} value={store.charges.find(item => item.id === modal.id)} onClose={() => setModal(null)} onSave={patch => saveEdit(updatePsychologyChargeInLedger(store, modal.id, patch), 'Cobrança atualizada.')} />}
    {modal !== null && typeof modal === 'object' && modal.type === 'payment' && <PaymentEditDialog value={store.payments.find(item => item.id === modal.id)} onClose={() => setModal(null)} onSave={patch => saveEdit(updatePsychologyPaymentInLedger(store, modal.id, patch), 'Pagamento atualizado.')} />}
    {modal !== null && typeof modal === 'object' && modal.type === 'paymentForCharge' && <PaymentDialog store={store} patientId={patientId} initialChargeId={modal.id} onClose={() => setModal(null)} onSave={input => void Promise.resolve(saveMutation(createPsychologyPaymentInLedger(store, input), 'Pagamento registrado.'))} />}
    {modal !== null && typeof modal === 'object' && modal.type === 'expense' && <ExpenseEditDialog value={store.expenses.find(item => item.id === modal.id)} onClose={() => setModal(null)} onSave={patch => saveEdit(updatePsychologyExpenseInLedger(store, modal.id, patch), 'Despesa atualizada.')} />}
    {modal !== null && typeof modal === 'object' && modal.type === 'package' && <PackageDialog store={store} value={store.sessionPackages.find(item => item.id === modal.id)} onClose={() => setModal(null)} onSave={input => saveEdit(upsertPsychologySessionPackageInLedger(store, input, modal.id), 'Pacote atualizado.')} />}
    {reasonRequest && <ReasonDialog type={reasonRequest.type} reason={reason} setReason={setReason} onClose={() => setReasonRequest(null)} onConfirm={confirmReason} />}
    {processing && <div className="fixed inset-0 z-[400] flex items-center justify-center bg-slate-950/15" role="status" data-testid="psychology-finance-mutation-processing"><div className="rounded-xl bg-white px-4 py-3 text-sm font-black text-slate-800 shadow-xl">Salvando financeiro…</div></div>}
  </div>;
}

function OverviewPanel({ overview, onTab, packageCount }: { overview: ReturnType<typeof getPsychologyFinancialOverview>; onTab: (tab: FinanceTab) => void; packageCount: number }) {
  return <div className="grid gap-4 lg:grid-cols-2"><section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><CircleDollarSign size={18} className="text-violet-700" /><h4 className="text-lg font-black">Resumo do período</h4></div><p className="mt-2 text-sm text-slate-500">Vencido é um subconjunto de A receber e não é somado novamente ao saldo.</p><div className="mt-4 space-y-2 text-sm"><SummaryLine label="Recebimentos em caixa" value={formatPsychologyMoney(overview.received)} /><SummaryLine label="Cobranças em aberto" value={formatPsychologyMoney(overview.receivable)} /><SummaryLine label="Despesas realizadas" value={formatPsychologyMoney(overview.expenses)} /><SummaryLine label="Saldo realizado" value={formatPsychologyMoney(overview.balance)} /></div></section><section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><CalendarDays size={18} className="text-violet-700" /><h4 className="text-lg font-black">Acesso rápido</h4></div><div className="mt-4 grid gap-2 sm:grid-cols-4"><button type="button" onClick={() => onTab('charges')} className={smallButton}><Receipt size={15} /> Cobranças</button><button type="button" onClick={() => onTab('packages')} className={smallButton}><WalletCards size={15} /> Pacotes</button><button type="button" onClick={() => onTab('payments')} className={smallButton}><WalletCards size={15} /> Pagamentos</button><button type="button" onClick={() => onTab('expenses')} className={smallButton}><Banknote size={15} /> Despesas</button></div><p className="mt-3 text-xs font-bold text-slate-500">{packageCount} pacote(s) ativo(s) com saldo de sessões.</p></section></div>;
}

function SummaryLine({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-3 border-b border-slate-100 pb-2 last:border-0 last:pb-0"><span className="font-bold text-slate-600">{label}</span><strong className="text-slate-900">{value}</strong></div>; }

function ReasonDialog({ type, reason, setReason, onClose, onConfirm }: { type: ReasonRequest['type']; reason: string; setReason: (value: string) => void; onClose: () => void; onConfirm: () => void }) {
  const copy = type === 'charge' ? { title: 'Cancelar cobrança?', impact: 'A cobrança continuará no histórico, mas deixará de compor A receber e Vencido.' } : type === 'payment' ? { title: 'Estornar pagamento?', impact: 'O recebimento ativo será removido e o saldo da cobrança será recalculado.' } : { title: 'Estornar despesa?', impact: 'A despesa permanecerá no histórico, mas deixará de compor despesas realizadas e saldo.' };
  return <FinanceDialog title={copy.title} onClose={onClose}><p className="rounded-xl border border-amber-200 bg-amber-50 px-3 py-3 text-sm font-bold text-amber-900">{copy.impact}</p><label className="block space-y-1.5"><span className="text-xs font-black text-slate-600">Motivo obrigatório</span><textarea autoFocus value={reason} onChange={event => setReason(event.target.value)} placeholder="Descreva o motivo da correção" className={`${inputClass} min-h-24`} /></label><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Voltar</button><button type="button" onClick={onConfirm} disabled={!reason.trim()} className={primaryButton}><RotateCcw size={15} /> Confirmar correção</button></div></FinanceDialog>;
}

function ActionButtons({ active, onEdit, onDeactivate, onReactivate, onPay, writeBlocked, editLabel = 'Editar' }: { active: boolean; onEdit: () => void; onDeactivate?: () => void; onReactivate: () => void; onPay?: () => void; writeBlocked: boolean; editLabel?: string }) {
  return <span className="flex flex-wrap items-center gap-1"><button type="button" onClick={onEdit} disabled={writeBlocked} className={smallButton} aria-label={editLabel}><Pencil size={13} /> {editLabel}</button>{onPay && <button type="button" onClick={onPay} disabled={writeBlocked} className={`${smallButton} text-emerald-700`} aria-label="Registrar pagamento"><WalletCards size={13} /> Registrar pagamento</button>}{active && onDeactivate ? <button type="button" onClick={onDeactivate} disabled={writeBlocked} className={`${smallButton} text-rose-700`} aria-label="Desativar">Desativar</button> : <button type="button" onClick={onReactivate} disabled={writeBlocked} className={`${smallButton} text-emerald-700`} aria-label="Reativar"><RotateCcw size={13} /> Reativar</button>}</span>;
}

function ChargesList({ charges, patientMap, serviceMap, packageMap, onCancel, onReactivate, onEdit, onPay, writeBlocked }: { charges: ReturnType<typeof getPsychologyFinancialLedger>['chargeEntries']; patientMap: Map<string, PsychologyPatient>; serviceMap: Map<string, { name: string }>; packageMap: Map<string, PsychologySessionPackage>; onCancel: (id: string) => void; onReactivate: (id: string) => void; onEdit: (id: string) => void; onPay: (id: string) => void; writeBlocked: boolean }) {
  return <div className="overflow-x-auto"><div className="min-w-[1120px]"><div className="grid grid-cols-[1.1fr_1.5fr_1.1fr_.8fr_.8fr_.8fr_.8fr_1fr_2.2fr] gap-3 px-4 py-3 text-[11px] font-black uppercase tracking-wide text-slate-500"><span>Paciente</span><span>Descrição</span><span>Vínculo</span><span>Valor</span><span>Recebido</span><span>Saldo</span><span>Vencimento</span><span>Status</span><span>Ações</span></div>{charges.length ? charges.map(entry => <div key={entry.charge.id} className="grid grid-cols-[1.1fr_1.5fr_1.1fr_.8fr_.8fr_.8fr_.8fr_1fr_2.2fr] items-center gap-3 border-t border-slate-100 px-4 py-3 text-sm"><span className="truncate font-black">{patientMap.get(entry.charge.patientId || '')?.name || 'Paciente não encontrado'}</span><span className="truncate text-slate-600">{entry.charge.description || 'Sem descrição'}</span><span className="min-w-0 truncate text-xs text-slate-500">{entry.charge.packageId ? `Pacote: ${packageMap.get(entry.charge.packageId)?.name || 'não encontrado'}` : entry.charge.serviceId ? `Serviço: ${serviceMap.get(entry.charge.serviceId)?.name || 'não encontrado'}` : 'Avulsa'}</span><span className="font-bold">{formatPsychologyMoney(entry.charge.amount)}</span><span className="font-bold text-emerald-700">{formatPsychologyMoney(entry.received)}</span><span className="font-bold text-amber-700">{formatPsychologyMoney(entry.balance)}</span><span className="text-slate-600">{dateLabel(entry.charge.dueDate)}</span><span className={`inline-flex w-fit rounded-full px-2 py-1 text-[11px] font-black ${statusClass(entry.status, entry.overdue)}`}>{chargeStatusLabel(entry.status, entry.overdue)}</span><ActionButtons active={entry.status !== 'CANCELLED'} onEdit={() => onEdit(entry.charge.id)} onPay={entry.status !== 'CANCELLED' && entry.balance > 0 ? () => onPay(entry.charge.id) : undefined} onDeactivate={entry.status !== 'CANCELLED' && entry.status !== 'PAID' ? () => onCancel(entry.charge.id) : undefined} onReactivate={() => onReactivate(entry.charge.id)} writeBlocked={writeBlocked} /></div>) : <p className="border-t border-slate-100 px-4 py-8 text-center text-sm font-bold text-slate-500">Nenhuma cobrança encontrada.</p>}</div></div>;
}

function PaymentsList({ payments, charges, patientMap, packageMap, onReverse, onReactivate, onEdit, writeBlocked }: { payments: PsychologyPayment[]; charges: PsychologyCharge[]; patientMap: Map<string, PsychologyPatient>; packageMap: Map<string, PsychologySessionPackage>; onReverse: (id: string) => void; onReactivate: (id: string) => void; onEdit: (id: string) => void; writeBlocked: boolean }) {
  const chargeMap = new Map(charges.map(charge => [charge.id, charge]));
  return <div className="overflow-x-auto"><div className="min-w-[920px]"><div className="grid grid-cols-[.8fr_1.2fr_1.5fr_.8fr_1fr_1fr_1.5fr] gap-3 px-4 py-3 text-[11px] font-black uppercase tracking-wide text-slate-500"><span>Data</span><span>Paciente</span><span>Cobrança</span><span>Valor</span><span>Meio</span><span>Status</span><span>Ações</span></div>{payments.length ? payments.map(payment => { const active = isPsychologyPaymentActive(payment); const charge = chargeMap.get(payment.chargeId || ''); return <div key={payment.id} className="grid grid-cols-[.8fr_1.2fr_1.5fr_.8fr_1fr_1fr_1.5fr] items-center gap-3 border-t border-slate-100 px-4 py-3 text-sm"><span className="text-slate-600">{dateLabel(payment.date)}</span><span className="truncate font-black">{patientMap.get(payment.patientId || '')?.name || 'Paciente não encontrado'}</span><span className="truncate text-slate-600">{charge?.packageId ? `Pacote: ${packageMap.get(charge.packageId)?.name || 'não encontrado'}` : charge?.description || 'Cobrança vinculada'}</span><span className="font-black text-emerald-700">{formatPsychologyMoney(payment.amount)}</span><span>{paymentMethods.find(method => method.value === payment.method)?.label || payment.method}</span><span className={`inline-flex w-fit rounded-full px-2 py-1 text-[11px] font-black ${active ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>{active ? 'Ativo' : 'Estornado'}</span><ActionButtons active={active} onEdit={() => onEdit(payment.id)} onDeactivate={() => onReverse(payment.id)} onReactivate={() => onReactivate(payment.id)} writeBlocked={writeBlocked} /></div>; }) : <p className="border-t border-slate-100 px-4 py-8 text-center text-sm font-bold text-slate-500">Nenhum pagamento encontrado.</p>}</div></div>;
}

function ExpensesList({ expenses, onReverse, onReactivate, onEdit, writeBlocked }: { expenses: PsychologyExpense[]; onReverse: (id: string) => void; onReactivate: (id: string) => void; onEdit: (id: string) => void; writeBlocked: boolean }) {
  return <div className="overflow-x-auto"><div className="min-w-[820px]"><div className="grid grid-cols-[.8fr_1.7fr_1.1fr_1fr_1fr_1.5fr] gap-3 px-4 py-3 text-[11px] font-black uppercase tracking-wide text-slate-500"><span>Data</span><span>Descrição</span><span>Categoria</span><span>Valor</span><span>Status</span><span>Ações</span></div>{expenses.length ? expenses.map(expense => <div key={expense.id} className="grid grid-cols-[.8fr_1.7fr_1.1fr_1fr_1fr_1.5fr] items-center gap-3 border-t border-slate-100 px-4 py-3 text-sm"><span className="text-slate-600">{dateLabel(expense.date)}</span><span className="truncate font-black">{expense.description || 'Sem descrição'}</span><span>{expense.category}</span><span className="font-black text-slate-900">{formatPsychologyMoney(expense.amount)}</span><span className={`inline-flex w-fit rounded-full px-2 py-1 text-[11px] font-black ${expense.status === 'REALIZED' ? 'bg-emerald-50 text-emerald-700' : expense.status === 'PENDING' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{expense.status === 'REALIZED' ? 'Realizada' : expense.status === 'PENDING' ? 'Pendente' : 'Estornada'}</span><ActionButtons active={expense.status !== 'REVERSED'} onEdit={() => onEdit(expense.id)} onDeactivate={() => onReverse(expense.id)} onReactivate={() => onReactivate(expense.id)} writeBlocked={writeBlocked} /></div>) : <p className="border-t border-slate-100 px-4 py-8 text-center text-sm font-bold text-slate-500">Nenhuma despesa encontrada.</p>}</div></div>;
}

function PackagesList({ packages, patientMap, serviceMap, chargeEntries, onEdit, onToggle, onPay, writeBlocked }: { packages: PsychologySessionPackage[]; patientMap: Map<string, PsychologyPatient>; serviceMap: Map<string, { name: string }>; chargeEntries: ReturnType<typeof getPsychologyFinancialLedger>['chargeEntries']; onEdit: (id: string) => void; onToggle: (item: PsychologySessionPackage) => void; onPay?: (id: string) => void; writeBlocked: boolean }) {
  return <div className="overflow-x-auto"><div className="min-w-[1180px]"><div className="grid grid-cols-[1.15fr_1.4fr_.9fr_1fr_1fr_1fr_1.8fr] gap-3 px-4 py-3 text-[11px] font-black uppercase tracking-wide text-slate-500"><span>Paciente</span><span>Pacote / serviço</span><span>Uso</span><span>Valor</span><span>Recebido</span><span>Saldo</span><span>Status / ações</span></div>{packages.length ? packages.map(item => { const linkedCharges = chargeEntries.filter(entry => entry.charge.packageId === item.id); const received = linkedCharges.reduce((sum, entry) => sum + entry.received, 0); const balance = linkedCharges.reduce((sum, entry) => sum + entry.balance, 0); return <div key={item.id} className="grid grid-cols-[1.15fr_1.4fr_.9fr_1fr_1fr_1fr_1.8fr] items-center gap-3 border-t border-slate-100 px-4 py-3 text-sm"><span className="truncate font-black">{patientMap.get(item.patientId)?.name || 'Paciente não encontrado'}</span><span className="min-w-0"><strong className="block truncate">{item.name}</strong><span className="block truncate text-xs text-slate-500">{item.serviceId ? serviceMap.get(item.serviceId)?.name || 'Serviço não encontrado' : 'Serviço não vinculado'}</span></span><span className="font-bold">{item.usedSessions}/{item.totalSessions} sessões</span><span className="font-bold">{formatPsychologyMoney(item.totalPrice ?? item.price ?? 0)}</span><span className="font-bold text-emerald-700">{formatPsychologyMoney(received)}</span><span className="font-bold text-amber-700">{formatPsychologyMoney(balance)}</span><span className="flex flex-wrap items-center gap-1"><span className={`inline-flex w-fit rounded-full px-2 py-1 text-[11px] font-black ${item.active ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>{item.active ? 'Ativo' : 'Inativo'}</span><ActionButtons active={item.active} onEdit={() => onEdit(item.id)} onPay={balance > 0 && onPay ? () => onPay(item.id) : undefined} onDeactivate={() => onToggle(item)} onReactivate={() => onToggle(item)} writeBlocked={writeBlocked} /></span></div>; }) : <p className="border-t border-slate-100 px-4 py-8 text-center text-sm font-bold text-slate-500">Nenhum pacote encontrado.</p>}</div></div>;
}

function ChargeDialog({ store, initialPatientId, initialDraft, onClose, onCreatePackage: onCreatePackageAction, onSave }: { store: PsychologyStore; initialPatientId?: string; initialDraft?: ChargeDraft; onClose: () => void; onCreatePackage: (draft: ChargeDraft) => void; onSave: (input: { patientId: string; description: string; amount: number; dueDate?: string; sessionId?: string; serviceId?: string; packageId?: string; exempt?: boolean; exemptionReason?: string }) => void }) {
  const [patientId, setPatientId] = useState(initialDraft?.patientId || initialPatientId || ''); const [description, setDescription] = useState(initialDraft?.description || ''); const [money, setMoney] = useState(initialDraft?.money || ''); const [dueDate, setDueDate] = useState(initialDraft?.dueDate || ''); const [sessionId, setSessionId] = useState(initialDraft?.sessionId || ''); const [serviceId, setServiceId] = useState(initialDraft?.serviceId || ''); const [packageId, setPackageId] = useState(initialDraft?.packageId || ''); const [exempt, setExempt] = useState(initialDraft?.exempt || false); const [exemptionReason, setExemptionReason] = useState(initialDraft?.exemptionReason || '');
  const onCreatePackage = () => onCreatePackageAction({ patientId, description, money, dueDate, sessionId, serviceId, packageId, exempt, exemptionReason });
  const patientSessions = store.sessions.filter(session => session.patientId === patientId && session.status !== 'cancelada').sort((a, b) => `${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`));
  const patientPackages = store.sessionPackages.filter(item => item.patientId === patientId && item.active);
  const selectedService = store.services.find(service => service.id === serviceId);
  const selectedPackage = patientPackages.find(item => item.id === packageId);
  const amount = parsePsychologyMoney(money);
  return <FinanceDialog title="Nova cobrança" onClose={onClose}><Field label="Paciente *"><select autoFocus={!initialPatientId} disabled={Boolean(initialPatientId)} value={patientId} onChange={event => { setPatientId(event.target.value); setSessionId(''); setPackageId(''); setMoney(''); }} className={inputClass}><option value="">Selecione um paciente</option>{store.patients.filter(patient => patient.active).sort((a, b) => a.name.localeCompare(b.name)).map(patient => <option key={patient.id} value={patient.id}>{patient.name}</option>)}</select></Field><Field label="Descrição (opcional)"><input value={description} onChange={event => setDescription(event.target.value)} placeholder="Ex.: Sessão de psicoterapia" className={inputClass} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor (R$) *"><MoneyInput value={money} onChange={setMoney} placeholder={selectedPackage ? formatPsychologyMoneyInput(selectedPackage.totalPrice ?? selectedPackage.price) : selectedService ? formatPsychologyMoneyInput(selectedService.defaultPrice) : undefined} /></Field><Field label="Vencimento (opcional)"><input type="date" value={dueDate} onChange={event => setDueDate(event.target.value)} className={inputClass} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Sessão (opcional)"><select value={sessionId} onChange={event => setSessionId(event.target.value)} className={inputClass}><option value="">Sem sessão vinculada</option>{patientSessions.map(session => <option key={session.id} value={session.id}>{dateLabel(session.date)} · {session.time}</option>)}</select></Field><Field label="Serviço (opcional)"><select value={serviceId} onChange={event => { setServiceId(event.target.value); setPackageId(''); const service = store.services.find(item => item.id === event.target.value); if (service && !money) setMoney(formatPsychologyMoneyInput(service.defaultPrice)); }} className={inputClass}><option value="">Sem serviço</option>{store.services.filter(service => service.active).map(service => <option key={service.id} value={service.id}>{service.name}</option>)}</select></Field></div><div className="flex items-end gap-2"><Field label="Pacote (opcional)"><select value={packageId} onChange={event => { const nextId = event.target.value; const nextPackage = patientPackages.find(item => item.id === nextId); setPackageId(nextId); if (nextPackage) { setMoney(formatPsychologyMoneyInput(nextPackage.totalPrice ?? nextPackage.price)); if (nextPackage.serviceId) setServiceId(nextPackage.serviceId); } }} className={inputClass}><option value="">Sem pacote</option>{patientPackages.map(item => <option key={item.id} value={item.id}>{item.name} · {formatPsychologyMoney(item.totalPrice ?? item.price ?? 0)}</option>)}</select></Field><button type="button" onClick={onCreatePackage} className={`${secondaryButton} shrink-0`}><Plus size={14} /> Criar pacote</button></div><label className="flex items-start gap-3 rounded-xl border border-violet-200 bg-violet-50/60 p-3 text-sm"><input type="checkbox" checked={exempt} onChange={event => setExempt(event.target.checked)} className="mt-0.5" /><span><strong className="block text-violet-950">Isento / cortesia</strong><span className="text-xs font-bold text-violet-800">Não gera pagamento e não fica vencido.</span></span></label>{exempt && <Field label="Justificativa opcional"><input value={exemptionReason} onChange={event => setExemptionReason(event.target.value)} placeholder="Ex.: cortesia administrativa" className={inputClass} /></Field>}<div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={!patientId || amount === null} onClick={() => amount !== null && onSave({ patientId, sessionId: sessionId || undefined, description, amount, dueDate: dueDate || undefined, serviceId: serviceId || undefined, packageId: packageId || undefined, exempt, exemptionReason })} className={primaryButton}><Check size={16} /> Criar cobrança</button></div></FinanceDialog>;
}

function ChargeEditDialog({ store, value, onClose, onSave }: { store: PsychologyStore; value?: PsychologyCharge; onClose: () => void; onSave: (patch: Partial<Pick<PsychologyCharge, 'patientId' | 'description' | 'amount' | 'dueDate' | 'sessionId' | 'serviceId' | 'packageId' | 'exemptionReason'>>) => void }) {
  const [description, setDescription] = useState(value?.description || ''); const [money, setMoney] = useState(formatPsychologyMoneyInput(value?.amount)); const [dueDate, setDueDate] = useState(value?.dueDate || ''); const [serviceId, setServiceId] = useState(value?.serviceId || ''); const [packageId, setPackageId] = useState(value?.packageId || ''); const patientPackages = store.sessionPackages.filter(item => item.patientId === value?.patientId && (item.active || item.id === value?.packageId)); const amount = parsePsychologyMoney(money);
  if (!value) return null;
  return <FinanceDialog title="Editar cobrança" onClose={onClose}><Field label="Descrição (opcional)"><input autoFocus value={description} onChange={event => setDescription(event.target.value)} className={inputClass} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor (R$) *"><MoneyInput value={money} onChange={setMoney} /></Field><Field label="Vencimento (opcional)"><input type="date" value={dueDate} onChange={event => setDueDate(event.target.value)} className={inputClass} /></Field></div><Field label="Serviço (opcional)"><select value={serviceId} onChange={event => { setServiceId(event.target.value); setPackageId(''); }} className={inputClass}><option value="">Sem serviço</option>{store.services.filter(service => service.active).map(service => <option key={service.id} value={service.id}>{service.name}</option>)}</select></Field><Field label="Pacote (opcional)"><select value={packageId} onChange={event => { const nextId = event.target.value; const nextPackage = patientPackages.find(item => item.id === nextId); setPackageId(nextId); if (nextPackage) { setMoney(formatPsychologyMoneyInput(nextPackage.totalPrice ?? nextPackage.price)); if (nextPackage.serviceId) setServiceId(nextPackage.serviceId); } }} className={inputClass}><option value="">Sem pacote</option>{patientPackages.map(item => <option key={item.id} value={item.id}>{item.name} · {formatPsychologyMoney(item.totalPrice ?? item.price ?? 0)}</option>)}</select></Field><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={amount === null} onClick={() => amount !== null && onSave({ description, amount, dueDate: dueDate || undefined, serviceId: serviceId || undefined, packageId: packageId || undefined })} className={primaryButton}><Check size={16} /> Salvar cobrança</button></div></FinanceDialog>;
}

function PaymentDialog({ store, patientId, initialChargeId, onClose, onSave }: { store: PsychologyStore; patientId?: string; initialChargeId?: string; onClose: () => void; onSave: (input: { chargeId: string; patientId: string; amount: number; date: string; method: PsychologyPaymentMethod }) => void }) {
  const ledger = getPsychologyFinancialLedger(store); const [chargeId, setChargeId] = useState(initialChargeId || ''); const [money, setMoney] = useState(''); const [date, setDate] = useState(psychologyCivilDate()); const [method, setMethod] = useState<PsychologyPaymentMethod>('PIX'); const selected = ledger.chargeEntries.find(entry => entry.charge.id === chargeId); const amount = parsePsychologyMoney(money);
  useEffect(() => { if (initialChargeId && selected) setMoney(formatPsychologyMoneyInput(selected.balance)); }, [initialChargeId, selected?.balance]);
  return <FinanceDialog title="Registrar pagamento" onClose={onClose}><Field label="Cobrança *"><select autoFocus={!initialChargeId} value={chargeId} onChange={event => { setChargeId(event.target.value); setMoney(''); }} className={inputClass}><option value="">Selecione uma cobrança</option>{ledger.chargeEntries.filter(entry => (!patientId || entry.charge.patientId === patientId) && entry.balance > 0 && entry.status !== 'EXEMPT' && entry.status !== 'CANCELLED').map(entry => <option key={entry.charge.id} value={entry.charge.id}>{store.patients.find(patient => patient.id === entry.charge.patientId)?.name || 'Paciente'} · {entry.charge.description || 'Sem descrição'} · saldo {formatPsychologyMoney(entry.balance)}</option>)}</select></Field>{selected && <div className="grid grid-cols-3 gap-2 rounded-xl border border-violet-100 bg-violet-50/60 p-3 text-center text-xs"><div><span className="block font-bold text-slate-500">Original</span><strong>{formatPsychologyMoney(selected.charge.amount)}</strong></div><div><span className="block font-bold text-slate-500">Recebido</span><strong>{formatPsychologyMoney(selected.received)}</strong></div><div><span className="block font-bold text-slate-500">Saldo</span><strong className="text-amber-700">{formatPsychologyMoney(selected.balance)}</strong></div></div>}<div className="grid gap-3 sm:grid-cols-2"><Field label="Valor recebido (R$) *"><MoneyInput value={money} onChange={setMoney} /></Field><Field label="Data *"><input type="date" value={date} onChange={event => setDate(event.target.value)} className={inputClass} /></Field></div><Field label="Meio de pagamento *"><select value={method} onChange={event => setMethod(event.target.value as PsychologyPaymentMethod)} className={inputClass}>{paymentMethods.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></Field><p className="rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">Pagamento parcial e múltiplos pagamentos são permitidos. O valor acima do saldo é bloqueado pelo ledger.</p><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={!selected || amount === null || amount <= 0 || !date} onClick={() => selected && amount !== null && onSave({ chargeId, patientId: selected.charge.patientId || '', amount, date, method })} className={primaryButton}><Check size={16} /> Registrar pagamento</button></div></FinanceDialog>;
}

function PaymentEditDialog({ value, onClose, onSave }: { value?: PsychologyPayment; onClose: () => void; onSave: (patch: Partial<Pick<PsychologyPayment, 'amount' | 'date' | 'method'>>) => void }) {
  const [money, setMoney] = useState(formatPsychologyMoneyInput(value?.amount)); const [date, setDate] = useState(value?.date || psychologyCivilDate()); const [method, setMethod] = useState<PsychologyPaymentMethod>(value?.method || 'PIX'); const amount = parsePsychologyMoney(money); if (!value) return null;
  return <FinanceDialog title="Editar pagamento" onClose={onClose}><Field label="Valor recebido (R$) *"><MoneyInput value={money} onChange={setMoney} autoFocus /></Field><Field label="Data *"><input type="date" value={date} onChange={event => setDate(event.target.value)} className={inputClass} /></Field><Field label="Meio de pagamento *"><select value={method} onChange={event => setMethod(event.target.value as PsychologyPaymentMethod)} className={inputClass}>{paymentMethods.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></Field><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={amount === null || amount <= 0 || !date} onClick={() => amount !== null && onSave({ amount, date, method })} className={primaryButton}><Check size={16} /> Salvar pagamento</button></div></FinanceDialog>;
}

function ExpenseDialog({ onClose, onSave }: { onClose: () => void; onSave: (input: PsychologyExpenseInput) => void }) {
  const [description, setDescription] = useState(''); const [money, setMoney] = useState(''); const [date, setDate] = useState(psychologyCivilDate()); const [category, setCategory] = useState<PsychologyExpenseCategory>('Outros'); const [status, setStatus] = useState<PsychologyExpenseStatus>('REALIZED'); const amount = parsePsychologyMoney(money);
  return <FinanceDialog title="Nova despesa" onClose={onClose}><Field label="Descrição (opcional)"><input autoFocus value={description} onChange={event => setDescription(event.target.value)} placeholder="Ex.: Aluguel da sala" className={inputClass} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor (R$) *"><MoneyInput value={money} onChange={setMoney} /></Field><Field label="Data *"><input type="date" value={date} onChange={event => setDate(event.target.value)} className={inputClass} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Categoria"><select value={category} onChange={event => setCategory(event.target.value as PsychologyExpenseCategory)} className={inputClass}>{categories.map(item => <option key={item} value={item}>{item}</option>)}</select></Field><Field label="Status"><select value={status} onChange={event => setStatus(event.target.value as PsychologyExpenseStatus)} className={inputClass}><option value="REALIZED">Realizada</option><option value="PENDING">Pendente</option></select></Field></div><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={amount === null || amount <= 0 || !date} onClick={() => amount !== null && onSave({ description, amount, date, category, status })} className={primaryButton}><Check size={16} /> Criar despesa</button></div></FinanceDialog>;
}

function ExpenseEditDialog({ value, onClose, onSave }: { value?: PsychologyExpense; onClose: () => void; onSave: (patch: Partial<Pick<PsychologyExpense, 'description' | 'amount' | 'date' | 'category' | 'status'>>) => void }) {
  const [description, setDescription] = useState(value?.description || ''); const [money, setMoney] = useState(formatPsychologyMoneyInput(value?.amount)); const [date, setDate] = useState(value?.date || psychologyCivilDate()); const [category, setCategory] = useState<PsychologyExpenseCategory>(value?.category || 'Outros'); const [status, setStatus] = useState<PsychologyExpenseStatus>(value?.status || 'REALIZED'); const amount = parsePsychologyMoney(money); if (!value) return null;
  return <FinanceDialog title="Editar despesa" onClose={onClose}><Field label="Descrição (opcional)"><input autoFocus value={description} onChange={event => setDescription(event.target.value)} className={inputClass} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor (R$) *"><MoneyInput value={money} onChange={setMoney} /></Field><Field label="Data *"><input type="date" value={date} onChange={event => setDate(event.target.value)} className={inputClass} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Categoria"><select value={category} onChange={event => setCategory(event.target.value as PsychologyExpenseCategory)} className={inputClass}>{categories.map(item => <option key={item} value={item}>{item}</option>)}</select></Field><Field label="Status"><select value={status} onChange={event => setStatus(event.target.value as PsychologyExpenseStatus)} className={inputClass}><option value="REALIZED">Realizada</option><option value="PENDING">Pendente</option></select></Field></div><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={amount === null || amount <= 0 || !date} onClick={() => amount !== null && onSave({ description, amount, date, category, status })} className={primaryButton}><Check size={16} /> Salvar despesa</button></div></FinanceDialog>;
}

function PackageDialog({ store, value, initialPatientId, onClose, onSave }: { store: PsychologyStore; value?: PsychologySessionPackage; initialPatientId?: string; onClose: () => void; onSave: (input: PsychologySessionPackageInput) => void }) {
  const initialTotal = value?.totalPrice ?? (value?.pricePerSession !== undefined ? value.pricePerSession * (value.totalSessions || 1) : value?.price);
  const [patientId, setPatientId] = useState(value?.patientId || initialPatientId || ''); const [serviceId, setServiceId] = useState(value?.serviceId || ''); const [quantity, setQuantity] = useState(String(value?.totalSessions || 3)); const [money, setMoney] = useState(formatPsychologyMoneyInput(initialTotal)); const [startDate, setStartDate] = useState(value?.startDate || psychologyCivilDate()); const [endDate, setEndDate] = useState(value?.endDate || ''); const [usedSessions, setUsedSessions] = useState(String(value?.usedSessions || 0)); const service = store.services.find(item => item.id === serviceId); const totalSessions = Number(quantity); const totalPrice = parsePsychologyMoney(money) ?? 0; const pricePerSession = totalSessions > 0 ? Math.round((totalPrice / totalSessions) * 100) / 100 : 0; const name = `${service?.name || 'Pacote de sessões'} · ${totalSessions || 'quantidade'} sessões`;
  return <FinanceDialog title={value ? 'Editar pacote' : 'Novo pacote'} onClose={onClose} wide><div className="rounded-2xl border border-violet-100 bg-violet-50/60 p-4"><p className="text-xs font-black uppercase tracking-[0.14em] text-violet-700">Pacote administrativo</p><p className="mt-1 text-sm font-bold text-violet-950">Informe o valor total negociado; o valor médio por sessão é calculado sem impor uma fórmula de desconto.</p></div><Field label="Paciente *"><select autoFocus={!value && !initialPatientId} disabled={Boolean(initialPatientId)} value={patientId} onChange={event => setPatientId(event.target.value)} className={inputClass}><option value="">Selecione um paciente</option>{store.patients.filter(patient => patient.active).sort((a, b) => a.name.localeCompare(b.name)).map(patient => <option key={patient.id} value={patient.id}>{patient.name}</option>)}</select></Field><Field label="Serviço *"><select value={serviceId} onChange={event => { setServiceId(event.target.value); const selected = store.services.find(item => item.id === event.target.value); if (selected && !money) setMoney(formatPsychologyMoneyInput(selected.defaultPrice)); }} className={inputClass}><option value="">Selecione um serviço</option>{store.services.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><div className="grid gap-3 sm:grid-cols-4"><div className="sm:col-span-2"><Field label="Quantidade de sessões *"><div className="flex flex-wrap gap-2">{['1', '2', '3', '5', '10'].map(item => <button type="button" key={item} onClick={() => setQuantity(item)} className={`rounded-xl px-3 py-2 text-xs font-black ${quantity === item ? 'bg-violet-700 text-white' : 'bg-slate-100 text-slate-700'}`}>{item} sessões</button>)}<input value={quantity} onChange={event => setQuantity(event.target.value.replace(/\D/g, ''))} inputMode="numeric" placeholder="Personalizado" className={`${inputClass} min-w-28 flex-1`} /></div></Field></div><Field label="Já utilizadas"><input value={usedSessions} onChange={event => setUsedSessions(event.target.value.replace(/\D/g, ''))} inputMode="numeric" className={inputClass} /></Field><Field label="Valor total do pacote"><MoneyInput value={money} onChange={setMoney} /></Field></div><div className="grid gap-3 sm:grid-cols-3"><Field label="Média por sessão"><output className={`${inputClass} block font-black text-violet-800`}>{formatPsychologyMoney(pricePerSession)}</output></Field><Field label="Início"><input type="date" value={startDate} onChange={event => setStartDate(event.target.value)} className={inputClass} /></Field><Field label="Fim (opcional)"><input type="date" value={endDate} onChange={event => setEndDate(event.target.value)} className={inputClass} /></Field></div><p className="text-xs font-semibold text-slate-500">Este fluxo registra o mesmo pacote usado pelo paciente, cobrança e pagamentos. O consumo de sessões continua seguindo o contrato de agenda já existente.</p><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" onClick={onClose} className={secondaryButton}>Fechar</button><button type="button" disabled={!patientId || !serviceId || !Number.isInteger(totalSessions) || totalSessions < 1 || !startDate} onClick={() => onSave({ patientId, name, serviceId, totalSessions, usedSessions: Math.min(totalSessions, Math.max(0, Number(usedSessions) || 0)), startDate, endDate: endDate || undefined, active: value?.active ?? true, price: totalPrice, pricePerSession, totalPrice })} className={primaryButton}><Check size={16} /> {value ? 'Salvar pacote' : 'Criar pacote'}</button></div></FinanceDialog>;
}
